mapper.select:
SELECT id, aggregate_type, aggregate_id, event_type, payload_json, status,
       attempts, next_attempt_at, created_at, published_at
FROM integration_outbox
WHERE status IN ('PENDING', 'FAILED', 'PROCESSING') AND next_attempt_at <= #{now}
ORDER BY created_at
LIMIT #{limit}

mapper.update:
UPDATE integration_outbox
SET status = 'PROCESSING', attempts = attempts + 1, next_attempt_at = #{retryAt}
WHERE id = #{id} AND status IN ('PENDING', 'FAILED', 'PROCESSING')
